<?php
require __DIR__.'/includes/bootstrap.php'; require_admin(); require __DIR__.'/includes/layout.php';
$id=(int)($_GET['edit']??0);$view=(int)($_GET['view']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$first=post_string('first_name',80);$last=post_string('last_name',80);$email=strtolower(post_string('email',190));$phone=post_string('phone',30);$birth=post_string('birth_date',10);$address=post_string('address',255);$errors=[];if($first===''||$last===''||$phone==='')$errors[]='First name, last name and phone are required.';if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if($birth!==''&&!valid_date($birth))$errors[]='Enter a valid birth date.';if(!$errors){try{if($id){$q=$pdo->prepare('UPDATE patients SET first_name=?,last_name=?,email=?,phone=?,birth_date=?,address=? WHERE id=?');$q->execute([$first,$last,$email?:null,$phone,$birth?:null,$address?:null,$id]);}else{$q=$pdo->prepare('INSERT INTO patients(first_name,last_name,email,phone,birth_date,address) VALUES(?,?,?,?,?,?)');$q->execute([$first,$last,$email?:null,$phone,$birth?:null,$address?:null]);$id=(int)$pdo->lastInsertId();}audit($pdo,'patient.saved','patient',$id);flash('success','Patient information saved.');redirect('patients.php');}catch(PDOException $e){$errors[]='That email is already used by another patient.';}}}
$edit=$id?$pdo->prepare('SELECT * FROM patients WHERE id=?'):null;if($edit){$edit->execute([$id]);$edit=$edit->fetch();}
$profile=null;$history=[];if($view){$q=$pdo->prepare('SELECT * FROM patients WHERE id=?');$q->execute([$view]);$profile=$q->fetch();$q=$pdo->prepare("SELECT a.*,CONCAT(d.first_name,' ',d.last_name) dentist FROM appointments a JOIN dentists d ON d.id=a.dentist_id WHERE patient_id=? ORDER BY appointment_date DESC,start_time DESC");$q->execute([$view]);$history=$q->fetchAll();}
$search=trim((string)($_GET['q']??''));$q=$pdo->prepare("SELECT p.*,(SELECT COUNT(*) FROM appointments a WHERE a.patient_id=p.id) appointment_count FROM patients p WHERE CONCAT(p.first_name,' ',p.last_name) LIKE ? OR p.email LIKE ? OR p.phone LIKE ? ORDER BY p.last_name,p.first_name");$like='%'.$search.'%';$q->execute([$like,$like,$like]);$patients=$q->fetchAll();page_header('Patient Management','patients');
?><?php if(!empty($errors)):?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif?><div class="grid panels"><section class="card"><div class="toolbar"><h2>Registered patients</h2><form class="filters"><input name="q" placeholder="Search name or contact" value="<?=e($search)?>"><button>Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Contact</th><th>Appointments</th><th>Actions</th></tr></thead><tbody><?php foreach($patients as $p):?><tr><td><strong><?=e($p['first_name'].' '.$p['last_name'])?></strong><br><small>Joined <?=date('M Y',strtotime($p['created_at']))?></small></td><td><?=e($p['phone'])?><br><small><?=e($p['email'])?></small></td><td><?=$p['appointment_count']?></td><td class="actions"><a class="btn secondary sm" href="?view=<?=$p['id']?>">Profile</a><a class="btn secondary sm" href="?edit=<?=$p['id']?>">Edit</a></td></tr><?php endforeach?><?php if(!$patients):?><tr><td colspan="4" class="empty">No patients match your search.</td></tr><?php endif?></tbody></table></div></section><section class="card"><h2><?=$edit?'Edit patient':'Add patient'?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><label>First name<input name="first_name" maxlength="80" required value="<?=e($edit['first_name']??'')?>"></label><label>Last name<input name="last_name" maxlength="80" required value="<?=e($edit['last_name']??'')?>"></label><label>Email<input type="email" name="email" maxlength="190" value="<?=e($edit['email']??'')?>"></label><label>Phone<input name="phone" maxlength="30" required value="<?=e($edit['phone']??'')?>"></label><label>Birth date<input type="date" name="birth_date" value="<?=e($edit['birth_date']??'')?>"></label><label class="full">Address<input name="address" maxlength="255" value="<?=e($edit['address']??'')?>"></label><div class="full"><button>Save patient</button> <?php if($edit):?><a class="btn secondary" href="patients.php">Cancel</a><?php endif?></div></form></section></div><?php if($profile):?><section class="card" style="margin-top:20px"><div class="toolbar"><div><h2><?=e($profile['first_name'].' '.$profile['last_name'])?></h2><span><?=e($profile['phone'])?> · <?=e($profile['email']?:'No email')?></span></div><a class="btn secondary" href="patients.php">Close</a></div><h2>Appointment history</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Service</th><th>Dentist</th><th>Status</th></tr></thead><tbody><?php foreach($history as $a):?><tr><td><?=date('M j, Y · g:i A',strtotime($a['appointment_date'].' '.$a['start_time']))?></td><td><?=e($a['service_name_snapshot'])?></td><td>Dr. <?=e($a['dentist'])?></td><td><?=status_badge($a['status'])?></td></tr><?php endforeach?><?php if(!$history):?><tr><td colspan="4" class="empty">No appointment history.</td></tr><?php endif?></tbody></table></div></section><?php endif?><?php page_footer();
